// Task 5: Ethiopia-anchored multi-country dataset.
// Every replacement asserts an exact occurrence count so a silent miss fails loudly.
const fs = require('fs');
const path = require('path');
const EN = '/Users/akamaotto/code/icubefarm/sponsor-workspace-prototype/pan-african-org/en';

const buf = new Map();
const load = (f) => {
  if (!buf.has(f)) buf.set(f, fs.readFileSync(path.join(EN, f), 'utf8'));
  return buf.get(f);
};
let ops = 0;
function rep(f, from, to, n = 1) {
  const s = load(f);
  const hits = s.split(from).length - 1;
  if (hits !== n) throw new Error(`${f}: expected ${n} of ${JSON.stringify(from.slice(0, 90))}, found ${hits}`);
  buf.set(f, s.split(from).join(to));
  ops++;
}
const ALL = fs.readdirSync(EN).filter((f) => f.endsWith('.html'));

/* ------------------------------------------------------------------ *
 * 1. People — org staff, every page (sidebar) plus data rows.
 * ------------------------------------------------------------------ */
for (const f of ALL) {
  rep(f, 'class="user-avatar">ME<', 'class="user-avatar">SB<');
  const n = (load(f).split('María Esono').length - 1);
  if (n) rep(f, 'María Esono', 'Selamawit Bekele', n);
  const p = (load(f).split('Pedro Nsue').length - 1);
  if (p) rep(f, 'Pedro Nsue', 'Dawit Haile', p);
  const a = (load(f).split('Ana Mangue').length - 1);
  if (a) rep(f, 'Ana Mangue', 'Tigist Alemu', a);
}

/* ------------------------------------------------------------------ *
 * 2. index.html — dashboard
 * ------------------------------------------------------------------ */
{
